    #define   LSb32KeyProtectFlagPair_bForbidPVR                  1
    #define   LSb16KeyProtectFlagPair_bForbidPVR                  1
    #define       bKeyProtectFlagPair_bForbidPVR               1
    #define   MSK32KeyProtectFlagPair_bForbidPVR                  0x00000002

    #define     BA_KeyProtectFlagPair_Reserved                 0x0000
