///                                    : DSS                       0x1
///               %unsigned 4  CipherType                0x0
///                                    : AES_128                   0x0
///                                    : DVBCSAv2_64               0x1
///                                    : DVBCSAv2Conformance_48     0x2
///                                    : DVBCSAv3_128              0x3
///                                    : TDES_56                   0x4
///                                    : TDES_112                  0x5
///                                    : MULTI2_64                 0x6
///                                    : Any128                    0x7
///                                    : Any64                     0x8
///                                    : Any32                     0x9
///               %unsigned 3  ChainingMode              0x0
///                                    : ECB                       0x0
///                                    : CBC                       0x1
///                                    : Counter                   0x2
///                                                 ###
///                                                 * Is it necessary?
///                                                 ###
///                                    : RCBC                      0x3
///                                                 ###
///                                                 * Other
///                                                 ###
///                                    : NoChaining                0x4
///                                                 ###
///                                                 * N/A
///                                                 ###
///               %unsigned 3  ResidueProcessingMode     0x0
///                                    : NoResidue                 0x0
///                                    : ClearResidue              0x1
///                                    : EXOR                      0x2
///                                    : CTS                       0x3
///               %unsigned 3  ShortPayloadProcessingMode 0x0
///                                    : NoShortPayload            0x0
///                                    : ClearShortPayload         0x1
///                                    : XORWithEncryptionOfIV1     0x2
///                                    : XORWithEncryptionOfIV2     0x3
///               %unsigned 2  KeyLen                    0x0
///                                    ###
///                                    * Specify the encryption key length:
///                                    * AES128, AES192, AES256,
///                                    * DES, TDES
///                                    ###
///               %unsigned 4  DataSkippingMode          0x0
///                                    : Normal_Skip_Header        0x0
///                                    : Skip_2B                   0x1
///                                    : Skip_4B                   0x2
///                                    : Skip_12B                  0x3
///                                    : Skip_18B                  0x4
