///                                    : No_IV                     0x0
///                                    : ClearIV_with_fixed_value     0x1
///                                    : IV_calculated_by_MDI      0x2
///                                    : IV_calculated_by_MDD      0x3
///                                    : 2IVs                      0x4
///               %unsigned 4  BlockSize                 0x0
///                                    : 64b_block                 0x2
///                                    : 96b_block                 0x3
///                                    : 128b_block                0x4
///                                    : 256b_block                0x8
///               %unsigned 1  DVBCSA2_Conformance       0x0
///                                    ###
///                                    * For DVBCSA2 Conformance
///                                    ###
///               %unsigned 4  Reserve0                  0x0
///     # # ----------------------------------------------------------
/// $ENDOFINTERFACE  # size:       4B, bits:      32b, padding:     0B
