//////
/// 
/// $INTERFACE SecureCtx               biu              (4,4)
///     # # ----------------------------------------------------------
///     @ 0x00000                      (P)
///     # 0x00000 SecMemBound          
///               $SecureMem           SecMemBound       REG          
///                                    ###
///                                    * Be used to check secure memory boundary
///                                    ###
///     @ 0x00008                      (P)
///     # 0x00008 DstMemBound          
///               $DstMem              DstMemBound       REG          
///                                    ###
///                                    * All output dst should be located within this boundary
///                                    ###
///     @ 0x00010                      (P)
///     # 0x00010 SecDtcmBound         
